//! Real framed service requests through one existing Shared/BuildHost owner.
use super::*;use crate::daemon::generation::{self,GenerationRequest};
fn request()->GenerationRequest{let(_,mut build,_,_)=crate::generation_test_fixture::fixture();build.policy_inputs.as_mut().unwrap().workspace_generators=vec![crate::GeneratorName::Deps];GenerationRequest{build,check:true}}
fn exchange(owner:&Arc<Shared>,request:&GenerationRequest,discovery:bool)->Result<(bool,Vec<u8>),Box<dyn std::error::Error>>{let identity=std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH)?.as_nanos();let endpoint=transport::Endpoint::generation(identity)?;let listener=transport::listener(&endpoint)?;let shared=Arc::clone(owner);let server=std::thread::Builder::new().name("generation-real-service-fixture".into()).stack_size(16*1024*1024).spawn(move||handle(listener.accept()?,&shared,discovery))?;let mut stream=transport::connect(&endpoint)?;transport::set_timeout(&mut stream,Duration::from_secs(300))?;protocol::send(&mut stream,&Request::Hello{version:protocol::VERSION,compiler:owner.compiler})?;assert!(matches!(protocol::receive::<Reply>(&mut stream)?,Reply::Hello{retiring:false,..}));protocol::send(&mut stream,&Request::Generate(request.clone()))?;let mut output=Vec::new();let outcome=generation::consume_for_test(&mut stream,request,&mut output);drop(stream);server.join().expect("actual service thread must not panic")?;outcome.map(|clean|(clean,output))}
#[test]fn actual_generation_service_uses_same_serialized_resident_host_for_check_write_and_warm_metadata(){let owner=shared();let mut request=request();let root=request.build.policy_inputs.as_ref().unwrap().workspace.as_ref().unwrap().root.clone();let target=root.join("code/engine/_generated/deps.dm");let initial=std::fs::read(&target).unwrap();let(clean,stdout)=exchange(&owner,&request,false).unwrap();assert!(!clean);assert_eq!(stdout.split(|b|*b==b'\n').filter(|line|!line.is_empty()).count(),2);assert_eq!(std::fs::read(&target).unwrap(),initial);request.check=false;let(clean,stdout)=exchange(&owner,&request,false).unwrap();assert!(clean);assert_ne!(std::fs::read(&target).unwrap(),initial);let report:serde_json::Value=serde_json::from_slice(stdout.split(|b|*b==b'\n').nth(1).unwrap()).unwrap();assert_eq!(report["rows"][0]["state"],"written");assert_eq!(report["committed"],true);let slot=owner.slot(std::fs::canonicalize(&request.build.project).unwrap(),Some(&request.build));let tree={let host=slot.lock_host().unwrap();Arc::clone(host.query_tree().unwrap())};let body=std::fs::read(&target).unwrap();let(clean,stdout)=exchange(&owner,&request,false).unwrap();assert!(clean);let report:serde_json::Value=serde_json::from_slice(stdout.split(|b|*b==b'\n').nth(1).unwrap()).unwrap();assert_eq!(report["rows"][0]["state"],"fresh");assert_eq!(report["committed"],false);assert_eq!(std::fs::read(&target).unwrap(),body);let host=slot.lock_host().unwrap();assert!(Arc::ptr_eq(&tree,host.query_tree().unwrap()));let state=host.query_state();let state=state.lock().unwrap();state.snapshot.as_ref().expect("same final current snapshot").workspace_native_read().unwrap();}
#[test]fn actual_generation_discovery_endpoint_and_missing_bootstrap_never_install_or_emit_report(){let owner=shared();let mut request=request();let target=request.build.policy_inputs.as_ref().unwrap().workspace.as_ref().unwrap().root.join("code/engine/_generated/deps.dm");let before=std::fs::read(&target).unwrap();let error=exchange(&owner,&request,true).err().unwrap();assert!(error.to_string().contains("compiler-generation endpoint"));assert!(owner.slots.lock().unwrap().is_empty());assert_eq!(std::fs::read(&target).unwrap(),before);std::fs::remove_file(&target).unwrap();request.check=false;assert!(exchange(&owner,&request,false).is_err());assert!(!target.exists());assert!(std::fs::read_dir(target.parent().unwrap()).unwrap().next().is_none());}
#[test]fn generation_request_supersession_key_distinguishes_check_write_and_prepare_only(){let request=request();let admitted=super::super::super::build_admission::validate(&request.build).unwrap().unwrap();let mut check=RequestKey::of(&request.build,&request.build.project,admitted.workspace_generators());let prepare=check.clone();check.command=RequestCommand::GenerationCheck;let mut write=check.clone();write.command=RequestCommand::GenerationWrite;assert_ne!(check,write);assert_ne!(prepare,check);assert_ne!(prepare,write);assert_eq!(SessionKey::of(request.build.project.clone(),Some(&request.build)),SessionKey::of(request.build.project.clone(),Some(&request.build)));}
